// Writes src/data/exchangeRates.ts from the ECB's daily euro reference rates (docs/adr/0016):
//
//   node scripts/exchange-rates.ts [start-date]
//
// The start date defaults to 2024-01-01. The ECB publishes around 16:00 CET on business days.
// Review the diff of the generated file like any other change.

import { writeFileSync } from 'node:fs'

const start = process.argv[2] ?? '2024-01-01'
if (!/^\d{4}-\d{2}-\d{2}$/.test(start)) {
  console.error('Usage: node scripts/exchange-rates.ts [YYYY-MM-DD]')
  process.exit(1)
}
// DKK first: every rate to DKK goes through it. ISK isn't published by the ECB.
const codes = ['DKK', 'GBP', 'SEK', 'NOK', 'USD', 'CNY']
const url = `https://data-api.ecb.europa.eu/service/data/EXR/D.${codes.join('+')}.EUR.SP00.A?startPeriod=${start}&format=csvdata`

const res = await fetch(url, { headers: { Accept: 'text/csv' } })
if (!res.ok) throw new Error(`ECB answered ${res.status} for ${url}`)
const [header, ...rows] = (await res.text()).trim().split(/\r?\n/)
const col = header.split(',')
const [iCur, iDate, iValue] = ['CURRENCY', 'TIME_PERIOD', 'OBS_VALUE'].map((c) => col.indexOf(c))
if ([iCur, iDate, iValue].includes(-1)) throw new Error(`Unexpected columns from the ECB: ${header}`)

const byDate = new Map<string, (number | null)[]>()
for (const row of rows) {
  const f = row.split(',')
  const c = codes.indexOf(f[iCur])
  const date = f[iDate]
  const value = Number(f[iValue])
  if (c === -1 || !/^\d{4}-\d{2}-\d{2}$/.test(date) || !(value > 0)) continue
  const values = byDate.get(date) ?? codes.map(() => null)
  values[c] = value
  byDate.set(date, values)
}
const days = [...byDate].sort(([a], [b]) => a.localeCompare(b))
if (days.length === 0) throw new Error('The ECB returned no rates.')

const out = `// Generated by scripts/exchange-rates.ts from the ECB's daily euro reference rates
// (docs/adr/0016): units of each currency per euro. Don't edit by hand: regenerate.

import type { DailyRates } from '../calc/exchangeRates'

export const dailyRates: DailyRates = {
  codes: ${JSON.stringify(codes)},
  days: [
${days.map(([d, v]) => `    [${JSON.stringify(d)}, ${JSON.stringify(v)}],`).join('\n')}
  ],
}
`
writeFileSync(new URL('../src/data/exchangeRates.ts', import.meta.url), out)
console.log(`Wrote ${days.length} days, ${days[0][0]} to ${days[days.length - 1][0]}.`)
